package com.hbm.machine.generator.stirling;
import com.hbm.api.machine.MachineView;import com.hbm.energy.*;import com.hbm.heat.HeatSource;import com.hbm.multiblock.DummyableBlock;import com.hbm.registry.HbmSounds;import java.math.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.SoundSource;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** Source TU diffusion generator; exact native HE buffer is replaced each cogged tick, no FE compatibility. */
public final class StirlingBlockEntity extends BlockEntity implements EnergyProvider,SidedEnergyConnector,MachineView {
 public final StirlingKind kind;private BigInteger powerBuffer=BigInteger.ZERO;public int heat,displayHeat,overspeed,warnCooldown;public boolean hasCog=true;public float spin,lastSpin;private List<PowerNode> nodes=List.of();private List<BlockPos> active=List.of();
 public StirlingBlockEntity(BlockPos pos,BlockState state){super(StirlingContent.ENTITY.get(),pos,state);kind=((StirlingBlock)state.getBlock()).kind;}
 @Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
 public static List<Direction> portSides(){return List.of(Direction.WEST,Direction.EAST,Direction.NORTH,Direction.SOUTH);}
 public boolean portConnects(BlockPos pos,Direction side){return side!=null&&side.getAxis().isHorizontal()&&worldPosition.relative(side).equals(pos);}
 private void updatePorts(ServerLevel server){var loaded=portSides().stream().map(worldPosition::relative).filter(pos->server.hasChunkAt(pos)&&server.getBlockState(pos).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(pos))).toList();if(!loaded.equals(active)||nodes.stream().anyMatch(PowerNode::isExpired)){disconnect();active=List.copyOf(loaded);var rebuilt=new ArrayList<PowerNode>();for(var pos:loaded){var side=Direction.getNearest(pos.getX()-worldPosition.getX(),0,pos.getZ()-worldPosition.getZ());var node=new PowerNode(pos).setConnections(new NodeConnection(pos.relative(side),side));HbmEnergy.nodespace(server).createNode(node);rebuilt.add(node);}nodes=List.copyOf(rebuilt);}for(var node:nodes)if(node.hasValidNet())node.addProvider(this);}
 private static BigInteger produced(int heat,double efficiency){double amount=heat*efficiency;if(Double.isFinite(amount)&&amount>=-0x1.0p63&&amount<0x1.0p63)return BigInteger.valueOf((long)amount);return new BigDecimal(heat).multiply(BigDecimal.valueOf(efficiency)).toBigInteger();}
 public static void tick(Level level,BlockPos pos,BlockState state,StirlingBlockEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);else machine.clientTick();}
 private void serverTick(ServerLevel server){updatePorts(server);if(hasCog){powerBuffer=BigInteger.ZERO;pullHeat();powerBuffer=produced(heat,kind==StirlingKind.CREATIVE?1:StirlingConfig.efficiency);if(warnCooldown>0)warnCooldown--;if(heat>kind.maxHeat()&&kind!=StirlingKind.CREATIVE){overspeed++;if(overspeed>60&&warnCooldown==0){warnCooldown=100;server.playSound(null,worldPosition.getX()+.5,worldPosition.getY()+1,worldPosition.getZ()+.5,HbmSounds.get("block.warnOverspeed"),SoundSource.BLOCKS,2,1);}if(overspeed>StirlingConfig.overspeedLimit){hasCog=false;server.explode(null,worldPosition.getX()+.5,worldPosition.getY()+1,worldPosition.getZ()+.5,5,false,Level.ExplosionInteraction.NONE);var front=DummyableBlock.facing(getBlockState());var side=front.getCounterClockWise();var cog=new StrayCogEntity(server,worldPosition.getX()+.5+front.getStepX(),worldPosition.getY()+1,worldPosition.getZ()+.5+front.getStepZ()).orientation(front.get3DDataValue()).metadata(kind.gear);cog.setDeltaMovement(side.getStepX(),1+(heat-kind.maxHeat())*.0001D,side.getStepZ());server.addFreshEntity(cog);setChanged();}}else overspeed=0;}else{overspeed=0;warnCooldown=0;}displayHeat=heat;var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<22500)player.connection.send(packet);dispatchScope.commit();}if(!hasCog&&powerBuffer.signum()>0)powerBuffer=powerBuffer.subtract(BigInteger.ONE);heat=0;setChanged();}
 private void pullHeat(){var below=level.getBlockEntity(worldPosition.below());if(below instanceof HeatSource source){int pulled=(int)(source.getHeatStored()*StirlingConfig.diffusion);if(pulled>0){source.useUpHeat(pulled);heat+=pulled;return;}}heat=Math.max(heat-Math.max(heat/1000,1),0);}
 private void clientTick(){float momentum=powerBuffer.floatValue()*50F/kind.maxHeat();if(kind==StirlingKind.CREATIVE)momentum=Math.min(momentum,45);lastSpin=spin;spin+=momentum;if(spin>=360){spin-=360;lastSpin-=360;}}
 @Override public boolean canConnect(Direction side){return side!=null&&side.getAxis().isHorizontal();}@Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}
 private static long legacy(BigInteger value){return value.max(BigInteger.valueOf(Long.MIN_VALUE)).min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}
 @Override public long getPower(){return legacy(powerBuffer);}@Override public long getMaxPower(){return getPower();}@Override public long getProviderSpeed(){return hasCog?getPower():0;}@Override public BigInteger getPowerExact(){return powerBuffer;}@Override public BigInteger getMaxPowerExact(){return powerBuffer;}@Override public BigInteger getProviderSpeedExact(){return hasCog?powerBuffer:BigInteger.ZERO;}@Override public void setPower(long amount){setPowerExact(BigInteger.valueOf(amount));}@Override public void setPowerExact(BigInteger amount){powerBuffer=amount;setChanged();}@Override public void usePower(long amount){usePowerExact(BigInteger.valueOf(amount));}@Override public void usePowerExact(BigInteger amount){if(amount.signum()<0||amount.compareTo(powerBuffer)>0)throw new IllegalArgumentException("Unavailable Stirling HE requested");powerBuffer=powerBuffer.subtract(amount);setChanged();}
 private void disconnect(){if(level instanceof ServerLevel server)for(var node:nodes)if(!node.isExpired())HbmEnergy.nodespace(server).destroyNode(node);nodes=List.of();active=List.of();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putString("powerBuffer",powerBuffer.toString());tag.putBoolean("hasCog",hasCog);tag.putInt("overspeed",overspeed);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);powerBuffer=tag.contains("powerBuffer",Tag.TAG_STRING)?new BigInteger(tag.getString("powerBuffer")):BigInteger.valueOf(tag.getLong("powerBuffer"));hasCog=tag.getBoolean("hasCog");overspeed=tag.getInt("overspeed");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();tag.putString("powerBuffer",powerBuffer.toString());tag.putInt("heat",displayHeat);tag.putBoolean("hasCog",hasCog);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){powerBuffer=tag.contains("powerBuffer",Tag.TAG_STRING)?new BigInteger(tag.getString("powerBuffer")):BigInteger.valueOf(tag.getLong("powerBuffer"));displayHeat=heat=tag.getInt("heat");hasCog=tag.getBoolean("hasCog");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 @Override public long energyStored(){return getPower();}@Override public long energyCapacity(){return getMaxPower();}@Override public BigInteger energyStoredExact(){return powerBuffer;}@Override public BigInteger energyCapacityExact(){return powerBuffer;}@Override public List<TankView> tanks(){return List.of();}@Override public List<ProgressView> progressBars(){return List.of(new ProgressView("gui.hbm.stirling.heat",displayHeat,kind.maxHeat(),0xff9900),new ProgressView("gui.hbm.stirling.overspeed",overspeed,StirlingConfig.overspeedLimit,0xff0000));}
}
